function drawMap(){const c=$('minimap').getContext('2d'),w=230,h=190,points=track.points.filter((p,i)=>i%8===0&&p.s<=track.length);let minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x)),minZ=Math.min(...points.map(p=>p.z)),maxZ=Math.max(...points.map(p=>p.z));let scale=Math.min((w-30)/(maxX-minX||1),(h-25)/(maxZ-minZ||1));const xy=p=>[w/2+(p.x-(minX+maxX)/2)*scale,h-13-(p.z-minZ)*scale];c.clearRect(0,0,w,h);c.lineWidth=5;c.lineCap='round';c.strokeStyle='#0008';c.beginPath();points.forEach((p,i)=>i?c.lineTo(...xy(p)):c.moveTo(...xy(p)));c.stroke();c.lineWidth=1.8;c.strokeStyle='#d5eceb70';c.stroke();for(let a of race.opponents){c.fillStyle='#ffb368';c.beginPath();c.arc(...xy(track.at(a.s)),2,0,Math.PI*2);c.fill()}c.fillStyle='#91f6cc';c.shadowColor='#91f6cc';c.shadowBlur=8;c.beginPath();c.arc(...xy(track.at(race.s)),4,0,Math.PI*2);c.fill();c.shadowBlur=0;const end=xy(track.at(track.length));c.fillStyle='#fff';c.fillRect(end[0]-3,end[1]-3,6,6)}
